using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
public class QrtBf16RangeStats {
 public long[] histogram = new long[256];
 public long zero, nonzero, invalidValues;
 public int rows, columns, eligibleRows, certifiedRows, uniqueRows;
 public List<int[]> duplicateGroups = new List<int[]>();
 public List<int[]> rejected = new List<int[]>();
 public static QrtBf16RangeStats Scan(string path, int rows, int columns) {
  byte[] bytes = File.ReadAllBytes(path);
  if(bytes.Length != rows * columns * 2) throw new Exception("Tensor size mismatch");
  var r = new QrtBf16RangeStats(); r.rows=rows; r.columns=columns;
  var rowMap = new Dictionary<string,List<int>>();
  var digest = SHA256.Create();
  for(int row=0;row<rows;++row) {
   var distinct = new HashSet<int>();
   string key=Convert.ToBase64String(digest.ComputeHash(bytes,row*columns*2,columns*2));
   List<int> groupRows;
   if(!rowMap.TryGetValue(key,out groupRows)){groupRows=new List<int>();rowMap.Add(key,groupRows);}
   if(groupRows.Count>0) for(int t=0;t<columns*2;++t) if(bytes[row*columns*2+t]!=bytes[groupRows[0]*columns*2+t]) throw new Exception("Digest collision");
   groupRows.Add(row);
   int low=256,high=-1,bad=0,tiny=0,special=0;
   for(int k=0;k<columns;++k) {
    int offset=(row*columns+k)*2;
    int word=bytes[offset] | (bytes[offset+1]<<8);
    distinct.Add(word);
    if((word & 32767)==0) {++r.zero; continue;}
    int e=(word>>7)&255; ++r.histogram[e]; ++r.nonzero;
    low=Math.Min(low,e);high=Math.Max(high,e);
    if(e<64 || e>190) {++bad;++r.invalidValues;}
    if(e<64) ++tiny;
    if(e==255) ++special;
   }
   if(bad==0) ++r.eligibleRows;
   if(high<0 || (low>=77 && high<=179)) ++r.certifiedRows;
   if(bad!=0) r.rejected.Add(new int[]{row,low,high,bad,tiny,special,distinct.Count,bytes[row*columns*2] | (bytes[row*columns*2+1]<<8)});
  }
  r.uniqueRows=rowMap.Count;
  foreach(var pair in rowMap) if(pair.Value.Count>1) r.duplicateGroups.Add(pair.Value.ToArray());
  return r;
 }
}
